Rules.InvariantScript:
Refresh(Book_Bookings);
Set(varMyBookingsFilter, "Upcoming");
ClearCollect(varMyBookings,
    Sort(
        Filter(Book_Bookings,
            BookedBy.Email = User().Email
        ),
        StartDateTime,
        SortOrder.Ascending
    )
)

