Rules.InvariantScript:
Sort(
    Filter(varMyBookings,
        If(varMyBookingsFilter = "Upcoming",
            EndDateTime >= Now(),
            true
        )
    ),
    StartDateTime,
    If(varMyBookingsFilter = "Upcoming", SortOrder.Ascending, SortOrder.Descending)
)
